package org.zhixiaoce.aperture;
import java.util.*;import android.app.Activity;import android.view.*;import android.widget.*;
public class EpisodeAppendTest {
 static int checks;static long time;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}static Object get(Object o,String n)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 static void down(View v){v.sendKey(new KeyEvent(++time,0,20,0,false));v.sendKey(new KeyEvent(time,1,20,0,false));}static void up(View v){v.sendKey(new KeyEvent(++time,0,19,0,false));}
 static CinemaCatalog.Line line(int count,boolean longNames){CinemaCatalog.Line l=new CinemaCatalog.Line("测试线路");for(int i=0;i<count;i++)l.episodes.add(new CinemaCatalog.Episode(longNames?"第"+(i+1)+"期：这是完整的节目标题，包含嘉宾名单和本期特别内容（完整版）":"第"+(i+1)+"集","https://example.invalid/"+i));return l;}
 @SuppressWarnings("unchecked")public static void main(String[] args)throws Exception{
  Activity a=new Activity();View primary=new View();int[] picked={-1};CinemaCatalog.Line longLine=line(53,true);CinemaEpisodeGrid p=new CinemaEpisodeGrid(a,Arrays.asList(longLine,line(5,false)),0,0,primary,(l,e)->{},(l,e)->picked[0]=e);TreeMap<Integer,Button> cards=(TreeMap<Integer,Button>)get(p,"cards");
  check(cards.size()==20,"initial 20 long-title cards only");View first=cards.get(0),last=cards.get(19);last.requestFocus();down(last);check(cards.size()==40&&View.focus==cards.get(21),"Down appends next episodes and enters same column");check(cards.get(0)==first&&cards.get(19)==last,"append keeps existing episode views");
  View.flushPosts();check(View.focus==cards.get(21),"posted focus remains on newly selected episode");down(cards.get(39));check(cards.size()==53&&View.focus==cards.get(41),"final partial batch appended");down(cards.get(52));check(cards.size()==53&&View.focus==cards.get(52),"last episode stops loading");
  cards.get(52).performClick();check(picked[0]==52,"appended episode keeps real playback index");check(cards.get(52).maxLines==Integer.MAX_VALUE&&cards.get(52).ellipsize==null,"long title remains complete");
  List<View> all=new ArrayList<>();walk(p,all);check(all.stream().noneMatch(v->v instanceof TextView&&Arrays.asList("上一组","下一组").contains(((TextView)v).text)),"no manual group buttons");
  p=new CinemaEpisodeGrid(a,Arrays.asList(line(30001,false)),0,29991,primary,(l,e)->{},(l,e)->{});cards=(TreeMap<Integer,Button>)get(p,"cards");check(cards.size()<=20&&cards.containsKey(29991),"late resume does not create 30000 views");View kept=cards.get(29991);up(cards.get(29980));check(cards.containsKey(29976)&&cards.get(29991)==kept,"Up prepends earlier batch and retains views");
  p=new CinemaEpisodeGrid(a,Arrays.asList(line(41,false)),0,0,primary,(l,e)->{},(l,e)->{});cards=(TreeMap<Integer,Button>)get(p,"cards");down(cards.get(19));check(cards.containsKey(23)&&View.focus==cards.get(23),"short labels use four-column Down");up(cards.get(0));check(View.focus==primary,"first row Up returns to Play");
  List<String> names=new ArrayList<>();for(CinemaCatalog.Episode e:longLine.episodes)names.add(e.name);int[] selected={-1};CinemaChoicePanel choice=new CinemaChoicePanel(a,new FrameLayout(a),"选集",names,19,true,i->selected[0]=i,()->{});GridLayout rows=(GridLayout)get(choice,"rows");View original=rows.getChildAt(0);key(choice,20);check(rows.getChildCount()==40&&(int)get(choice,"selected")==20,"playback drawer Down appends without page replacement");check(rows.getChildAt(0)==original,"drawer preserves original episode cards");
  for(int i=0;i<33;i++)key(choice,20);check(rows.getChildCount()==53&&(int)get(choice,"selected")==52,"drawer reaches final episode");key(choice,23);check(selected[0]==52,"drawer OK plays appended episode");
  choice=new CinemaChoicePanel(a,new FrameLayout(a),"选集",names,40,true,i->{},()->{});rows=(GridLayout)get(choice,"rows");original=rows.getChildAt(0);key(choice,19);check((int)get(choice,"selected")==39&&rows.getChildCount()==33&&rows.getChildAt(20)==original,"drawer Up prepends around resumed episode");
  choice=new CinemaChoicePanel(a,new FrameLayout(a),"换线路",Arrays.asList("线路1","线路2"),0,false,i->{},()->{});key(choice,20);check(((GridLayout)get(choice,"rows")).getChildCount()==2,"ordinary line menu remains unchanged");
  System.out.println(checks+" production episode append, full-title and focus assertions passed");
 }
 static void key(CinemaChoicePanel p,int code){p.key(new KeyEvent(++time,0,code,0,false));p.key(new KeyEvent(time,1,code,0,false));}static void walk(View v,List<View> out){out.add(v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)walk(((ViewGroup)v).getChildAt(i),out);}
}
